/**
 * All GROQ queries used by the site. Result types are generated by Sanity TypeGen
 * (`pnpm --filter @pescadors/studio typegen`), which scans this file for `defineQuery`.
 * Localised fields are fetched with all languages; views pick one with `pickLocale()`.
 */
import { defineQuery } from 'groq';

// Image with crop/hotspot, alt text and the low-quality placeholder.
// Kept inline in each query (not interpolated) so TypeGen can read it.

export const settingsQuery = defineQuery(`*[_type == "siteSettings" && _id == "siteSettings"][0]{
  clubName, tagline, logo, email, phone, address, mapUrl, social
}`);

export const homeQuery = defineQuery(`*[_type == "homePage" && _id == "homePage"][0]{
  heroTitle, heroBand, intro,
  heroImage{..., asset->{_id, metadata{lqip, dimensions}}}
}`);

export const postsQuery =
  defineQuery(`*[_type == "post" && defined(slug.current) && publishedAt <= now()] | order(publishedAt desc){
  _id, title, "slug": slug.current, publishedAt, excerpt, body,
  cover{..., asset->{_id, metadata{lqip, dimensions}}},
  "event": event->{title, "slug": slug.current},
  "album": album->{title, "slug": slug.current}
}`);

export const eventsQuery =
  defineQuery(`*[_type == "event" && defined(slug.current)] | order(start asc){
  _id, title, "slug": slug.current, kind, start, end, location, summary, body,
  registrationUrl, organisedByClub, programme, participatingClubs,
  poster{..., asset->{_id, metadata{lqip, dimensions}}},
  courseMap{..., asset->{_id, metadata{lqip, dimensions}}},
  "season": season->title,
  "competition": competition->name,
  "hasResults": count(*[_type == "result" && event._ref == ^._id]) > 0
}`);

export const resultsQuery =
  defineQuery(`*[_type == "result" && defined(event->slug.current)] | order(event->start desc){
  _id,
  "event": event->{title, "slug": slug.current, start, location, "season": season->title, "competition": competition->name},
  rows[]{
    _key, position, time, crew, notes,
    "category": category->{name, ageGroup, crew, order},
    "boatClass": boatClass->{name, order}
  },
  officialUrl,
  "officialFileUrl": officialFile.asset->url
}`);

export const albumsQuery =
  defineQuery(`*[_type == "album" && defined(slug.current)] | order(date desc){
  _id, title, "slug": slug.current, date,
  "event": event->{title, "slug": slug.current},
  images[]{..., asset->{_id, metadata{lqip, dimensions}}},
  videos[]{_key, url, title}
}`);

export const sponsorsQuery = defineQuery(`*[_type == "sponsor"
  && (!defined(activeFrom) || activeFrom <= $today)
  && (!defined(activeTo) || activeTo >= $today)] | order(order asc, name asc){
  _id, name, url, tier,
  logo{..., asset->{_id, metadata{dimensions}}}
}`);

export const clubPageQuery = defineQuery(`*[_type == "page" && slug.current == "el-club"][0]{
  title, body,
  image{..., asset->{_id, metadata{lqip, dimensions}}}
}`);
